PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?c ?label ?p ?o WHERE {
  ?c a ?type .
  FILTER(CONTAINS(STR(?type), "Constraint"))
  OPTIONAL { ?c rdfs:label ?label }
  OPTIONAL { ?c ?p ?o . FILTER(?p != rdfs:label && ?p != rdf:type) }
}
ORDER BY ?label ?c ?p

