PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?c ?label ?p ?o ?otype WHERE {
  ?c a ?type ; rdfs:label ?label ; ?p ?o .
  FILTER(CONTAINS(STR(?type), "Constraint"))
  FILTER(?p NOT IN (rdf:type, rdfs:label))
  OPTIONAL { ?o a ?otype }
  FILTER(CONTAINS(STR(?otype), "Rationale") || CONTAINS(STR(?otype), "rationale"))
}
ORDER BY ?label

